import { useEffect, useMemo, useRef, useState } from "react";
import maplibregl from "maplibre-gl";
import "maplibre-gl/dist/maplibre-gl.css";
import type { Feature, FeatureCollection, Polygon } from "geojson";
import type { RealSceneAreaSelection, RealSceneBounds, RealSceneMapMode } from "../../types/realSceneGeometry";
import type { RoadDetectionCoordinate } from "../../types/roadLayoutDetection";
import { areaSelectionFromBounds } from "../../services/forensicAreaService";

interface Props {
  anchor: RoadDetectionCoordinate | null;
  coreArea: RealSceneAreaSelection | null;
  contextArea: RealSceneAreaSelection | null;
  onAnchorChange(coordinate: RoadDetectionCoordinate): void;
  onCoreAreaChange(area: RealSceneAreaSelection | null): void;
}

const DEFAULT_CENTER: [number, number] = [31.053, -17.825];
const STREET_STYLE = "https://tiles.openfreemap.org/styles/liberty";

function rasterStyle(tiles: string[], attribution: string) {
  return {
    version: 8 as const,
    sources: {
      raster: { type: "raster" as const, tiles, tileSize: 256, minzoom: 0, maxzoom: 17, attribution },
    },
    layers: [{ id: "raster-layer", type: "raster" as const, source: "raster" }],
  };
}

function styleForMode(mode: RealSceneMapMode) {
  if (mode === "hybrid") {
    return rasterStyle(
      ["https://server.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/{z}/{y}/{x}"],
      "Imagery © Esri",
    );
  }
  if (mode === "terrain") {
    return rasterStyle(
      ["https://server.arcgisonline.com/ArcGIS/rest/services/World_Topo_Map/MapServer/tile/{z}/{y}/{x}"],
      "Topographic map © Esri",
    );
  }
  return STREET_STYLE;
}

function polygonCollection(area: RealSceneAreaSelection | null): FeatureCollection<Polygon> {
  if (!area) return { type: "FeatureCollection", features: [] };
  const feature: Feature<Polygon> = {
    type: "Feature",
    properties: {},
    geometry: {
      type: "Polygon",
      coordinates: [area.polygon.map((point) => [point.longitude, point.latitude])],
    },
  };
  return { type: "FeatureCollection", features: [feature] };
}

function boundsFromCorners(
  first: { latitude: number; longitude: number },
  second: { latitude: number; longitude: number },
): RealSceneBounds {
  return {
    north: Math.max(first.latitude, second.latitude),
    south: Math.min(first.latitude, second.latitude),
    east: Math.max(first.longitude, second.longitude),
    west: Math.min(first.longitude, second.longitude),
  };
}

export default function ForensicAreaMap({ anchor, coreArea, contextArea, onAnchorChange, onCoreAreaChange }: Props) {
  const mountRef = useRef<HTMLDivElement | null>(null);
  const mapRef = useRef<maplibregl.Map | null>(null);
  const markerRef = useRef<maplibregl.Marker | null>(null);
  const firstCornerRef = useRef<{ latitude: number; longitude: number } | null>(null);
  const [mode, setMode] = useState<RealSceneMapMode>("hybrid");
  const [drawing, setDrawing] = useState(false);
  const [message, setMessage] = useState("Click the map to position the accident anchor.");
  const anchorKey = useMemo(() => (anchor ? `${anchor.latitude.toFixed(7)}:${anchor.longitude.toFixed(7)}` : "none"), [anchor]);

  useEffect(() => {
    const mount = mountRef.current;
    if (!mount) return;

    const map = new maplibregl.Map({
      container: mount,
      style: styleForMode(mode),
      center: anchor ? [anchor.longitude, anchor.latitude] : DEFAULT_CENTER,
      zoom: anchor ? 17 : 6,
      maxZoom: 17,
      pitch: 0,
      bearing: 0,
      attributionControl: false,
    });
    mapRef.current = map;
    map.addControl(new maplibregl.NavigationControl({ visualizePitch: false }), "bottom-right");
    map.addControl(new maplibregl.AttributionControl({ compact: true }), "bottom-left");

    const ensureLayers = () => {
      if (!map.getSource("forensic-context")) {
        map.addSource("forensic-context", { type: "geojson", data: polygonCollection(contextArea) });
        map.addLayer({ id: "forensic-context-fill", type: "fill", source: "forensic-context", paint: { "fill-color": "#a0a0a0", "fill-opacity": 0.07 } });
        map.addLayer({ id: "forensic-context-line", type: "line", source: "forensic-context", paint: { "line-color": "#a0a0a0", "line-opacity": 0.82, "line-width": 1.2, "line-dasharray": [3, 2] } });
      }
      if (!map.getSource("forensic-core")) {
        map.addSource("forensic-core", { type: "geojson", data: polygonCollection(coreArea) });
        map.addLayer({ id: "forensic-core-fill", type: "fill", source: "forensic-core", paint: { "fill-color": "#e8872d", "fill-opacity": 0.12 } });
        map.addLayer({ id: "forensic-core-line", type: "line", source: "forensic-core", paint: { "line-color": "#e8872d", "line-width": 2.2 } });
      }
    };

    map.on("load", ensureLayers);
    map.on("style.load", ensureLayers);

    const click = (event: maplibregl.MapMouseEvent) => {
      const coordinate: RoadDetectionCoordinate = {
        latitude: event.lngLat.lat,
        longitude: event.lngLat.lng,
        accuracyMetres: 0,
        capturedAt: new Date().toISOString(),
      };

      if (!drawing) {
        onAnchorChange(coordinate);
        setMessage("Accident anchor updated. Draw the forensic core when ready.");
        return;
      }

      const first = firstCornerRef.current;
      if (!first) {
        firstCornerRef.current = coordinate;
        setMessage("First corner fixed. Click the opposite corner.");
        return;
      }

      const area = areaSelectionFromBounds(boundsFromCorners(first, coordinate), {
        mapMode: mode,
        zoom: map.getZoom(),
        bearing: map.getBearing(),
        pitch: map.getPitch(),
      });
      firstCornerRef.current = null;
      setDrawing(false);
      onCoreAreaChange(area);
      setMessage("Forensic core selected. The grey context buffer is generated automatically.");
    };

    map.on("click", click);
    return () => {
      markerRef.current?.remove();
      markerRef.current = null;
      map.remove();
      mapRef.current = null;
    };
  }, [mode, drawing]);

  useEffect(() => {
    const map = mapRef.current;
    if (!map || !anchor) return;
    markerRef.current?.remove();
    const element = document.createElement("div");
    element.className = "roadsafe-forensic-anchor-marker";
    markerRef.current = new maplibregl.Marker({ element, anchor: "center" })
      .setLngLat([anchor.longitude, anchor.latitude])
      .addTo(map);
    if (anchorKey !== "none") {
      map.easeTo({ center: [anchor.longitude, anchor.latitude], zoom: Math.max(15, map.getZoom()), duration: 350 });
    }
  }, [anchorKey]);

  useEffect(() => {
    const map = mapRef.current;
    if (!map) return;
    const update = (id: string, area: RealSceneAreaSelection | null) => {
      const source = map.getSource(id) as maplibregl.GeoJSONSource | undefined;
      source?.setData(polygonCollection(area));
    };
    update("forensic-core", coreArea);
    update("forensic-context", contextArea);
  }, [coreArea, contextArea]);

  return (
    <section className="roadsafe-forensic-map">
      <div className="roadsafe-forensic-map__toolbar">
        <div className="roadsafe-forensic-map__modes">
          {(["street", "hybrid", "terrain"] as RealSceneMapMode[]).map((item) => (
            <button key={item} type="button" className={mode === item ? "is-active" : ""} onClick={() => setMode(item)}>{item}</button>
          ))}
        </div>
        <div className="roadsafe-forensic-map__actions">
          <button
            type="button"
            className={drawing ? "is-active" : ""}
            onClick={() => {
              firstCornerRef.current = null;
              setDrawing((current) => !current);
              setMessage(drawing ? "Core drawing cancelled." : "Click the first corner of the forensic core.");
            }}
          >
            {drawing ? "Cancel draw" : "Draw forensic core"}
          </button>
          <button type="button" onClick={() => { firstCornerRef.current = null; setDrawing(false); onCoreAreaChange(null); setMessage("Core cleared."); }}>Clear</button>
        </div>
      </div>
      <div ref={mountRef} className="roadsafe-forensic-map__canvas" />
      <div className="roadsafe-forensic-map__legend">
        <span><i className="is-core" />Forensic core</span>
        <span><i className="is-context" />Context buffer</span>
        <span><i className="is-anchor" />Accident anchor</span>
      </div>
      <p className="roadsafe-forensic-map__message">{message}</p>
    </section>
  );
}

